mapper.select:
SELECT O.OPPTY_ID, O.CUST_ID, C.CUST_NM, O.OPPTY_NM, O.STAGE_CD, O.EXPECT_AMT,
       O.EXPECT_CLOSE_DT, O.CHARGE_USER_ID, O.STATUS_CD, O.REG_DT
FROM TB_OPPTY O
LEFT OUTER JOIN TB_CUSTOMER C ON C.CUST_ID = O.CUST_ID


        O.CUST_ID = #{custId}


        AND O.STAGE_CD = #{stageCd}


        AND O.CHARGE_USER_ID = #{chargeUserId}


ORDER BY O.EXPECT_CLOSE_DT, O.OPPTY_ID
